class SessionInfo {
  const SessionInfo({
    required this.id,
    required this.agent,
    this.project,
    this.ticket,
    this.parent,
    required this.state,
    required this.lastSeq,
    this.contextTokens = 0,
    this.preview,
    required this.updated,
  });

  final String id;

  /// Agent definition name (`site://agents/<agent>`).
  final String agent;

  /// Active project directory, if any.
  final String? project;

  /// Set for worker sessions.
  final String? ticket;

  /// The session that spawned this one (orchestrator of a worker).
  final String? parent;

  final TurnState state;

  /// Last seq written to the transcript.
  final int lastSeq;

  /// Prompt tokens of the last model call: the context in use.
  final int contextTokens;

  /// Start of the last message, for session lists.
  final String? preview;

  /// RFC 3339.
  final String updated;

  factory SessionInfo.fromJson(Map<String, Object?> json) => SessionInfo(
        id: json['id'] as String,
        agent: json['agent'] as String,
        project: json['project'] == null ? null : json['project'] as String,
        ticket: json['ticket'] == null ? null : json['ticket'] as String,
        parent: json['parent'] == null ? null : json['parent'] as String,
        state: TurnState.fromJson(json['state']),
        lastSeq: (json['last_seq'] as num).toInt(),
        contextTokens: json['context_tokens'] == null ? 0 : (json['context_tokens'] as num).toInt(),
        preview: json['preview'] == null ? null : json['preview'] as String,
        updated: json['updated'] as String,
      );

  Map<String, Object?> toJson() => {
        'id': id,
        'agent': agent,
        if (project != null) 'project': project,
        if (ticket != null) 'ticket': ticket,
        if (parent != null) 'parent': parent,
        'state': state.toJson(),
        'last_seq': lastSeq,
        'context_tokens': contextTokens,
        if (preview != null) 'preview': preview,
        'updated': updated,
      };
}

